{
  "name": "tinker-exercise-api-design",
  "version": "0.2.0",
  "private": true,
  "description": "Practice: write OpenAPI YAML by hand, one step at a time",
  "type": "module",
  "scripts": {
    "lint": "node scripts/check-step.mjs --all-solutions",
    "check:step": "node scripts/check-step.mjs",
    "check:solutions": "node scripts/check-step.mjs --all-solutions",
    "check": "npm run check:solutions"
  },
  "engines": {
    "node": ">=20"
  },
  "devDependencies": {
    "@redocly/cli": "^1.34.3",
    "yaml": "^2.7.1"
  }
}

#!/usr/bin/env node
/**
 * Lint and assert required OpenAPI shapes for one step.
 *
 * Usage:
 *   node scripts/check-step.mjs 03
 *   node scripts/check-step.mjs 03 --solutions
 *   node scripts/check-step.mjs --all-solutions
 */
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import YAML from "yaml";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");

const STEPS = {
  "01": "01-smallest-valid-spec",
  "02": "02-name-the-thing",
  "03": "03-create",
  "04": "04-failure",
  "05": "05-lists",
  "06": "06-auth",
  "07": "07-from-scratch",
};

/** Step 00 is plain English only; no machine check. */
const NO_CHECK_STEPS = new Set(["00"]);

function fail(message) {
  console.error(`check:step: ${message}`);
  process.exit(1);
}

function loadSpec(filePath) {
  if (!fs.existsSync(filePath)) {
    fail(`missing file ${filePath}`);
  }
  const raw = fs.readFileSync(filePath, "utf8");
  const stripped = raw
    .split("\n")
    .filter((line) => !/^\s*#/.test(line))
    .join("\n")
    .trim();
  if (!stripped) {
    fail(`${filePath} is empty (comment-only files do not pass)`);
  }
  try {
    return YAML.parse(raw);
  } catch (err) {
    fail(`YAML parse failed for ${filePath}: ${err.message}`);
  }
}

function get(obj, dotted) {
  return dotted.split(".").reduce((acc, key) => (acc == null ? acc : acc[key]), obj);
}

function assert(condition, message) {
  if (!condition) fail(message);
}

function hasQueryParam(operation, name) {
  const params = operation?.parameters ?? [];
  return params.some((p) => p && p.name === name && p.in === "query");
}

function responseUsesRef(operation, status, refSuffix) {
  const content = operation?.responses?.[status]?.content?.["application/json"];
  const ref = content?.schema?.$ref;
  return typeof ref === "string" && ref.endsWith(refSuffix);
}

function lintFile(filePath) {
  const result = spawnSync(
    "npx",
    ["--no-install", "@redocly/cli", "lint", filePath, "--config", "redocly.yaml"],
    { cwd: ROOT, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }
  );
  if (result.status !== 0) {
    process.stdout.write(result.stdout || "");
    process.stderr.write(result.stderr || "");
    fail(`@redocly/cli lint failed for ${filePath}`);
  }
}

function checkStep01(spec) {
  assert(typeof spec.openapi === "string" && spec.openapi.startsWith("3."), "openapi version 3.x required");
  assert(typeof spec.info?.title === "string" && spec.info.title.length > 0, "info.title required");
  assert(typeof spec.info?.version === "string" && spec.info.version.length > 0, "info.version required");
  const getIntent = get(spec, "paths./payment_intents/{id}.get");
  assert(getIntent, "GET /payment_intents/{id} required");
  assert(getIntent.responses?.["200"], "GET /payment_intents/{id} must declare 200");
}

function checkStep02(spec) {
  checkStep01(spec);
  const intent = get(spec, "components.schemas.PaymentIntent");
  assert(intent && intent.type === "object", "components.schemas.PaymentIntent required");
  assert(
    responseUsesRef(get(spec, "paths./payment_intents/{id}.get"), "200", "/PaymentIntent"),
    "GET /payment_intents/{id} 200 must $ref PaymentIntent"
  );
}

function checkStep03(spec) {
  checkStep02(spec);
  const post = get(spec, "paths./payment_intents.post");
  assert(post, "POST /payment_intents required");
  assert(post.requestBody, "POST /payment_intents requestBody required");
  const create = get(spec, "components.schemas.CreatePaymentIntent")
    ?? Object.values(spec.components?.schemas ?? {}).find(
      (s) => Array.isArray(s?.required) && s.required.length > 0 && s !== get(spec, "components.schemas.PaymentIntent")
    );
  assert(create, "a create schema with required fields is required");
  assert(Array.isArray(create.required) && create.required.length > 0, "create schema must list required fields");
  const bodySchema = post.requestBody?.content?.["application/json"]?.schema;
  assert(bodySchema, "POST /payment_intents must accept application/json");
}

function checkStep04(spec) {
  checkStep03(spec);
  const error = get(spec, "components.schemas.Error");
  assert(error && error.type === "object", "components.schemas.Error required");
  const getIntent = get(spec, "paths./payment_intents/{id}.get");
  const post = get(spec, "paths./payment_intents.post");
  assert(getIntent.responses?.["404"] || post.responses?.["404"], "a 404 response is required");
  assert(getIntent.responses?.["400"] || post.responses?.["400"], "a 400 response is required");
  const usesError =
    responseUsesRef(getIntent, "404", "/Error") ||
    responseUsesRef(getIntent, "400", "/Error") ||
    responseUsesRef(post, "404", "/Error") ||
    responseUsesRef(post, "400", "/Error");
  assert(usesError, "400 or 404 must $ref Error");
}

function checkStep05(spec) {
  checkStep04(spec);
  const list = get(spec, "paths./payment_intents.get");
  assert(list, "GET /payment_intents required");
  assert(list.responses?.["200"], "GET /payment_intents must declare 200");
  const hasLimit = hasQueryParam(list, "limit");
  const hasOffset = hasQueryParam(list, "offset");
  const hasPage = hasQueryParam(list, "page");
  const hasCursor = hasQueryParam(list, "cursor");
  assert(
    (hasLimit && hasOffset) || hasPage || hasCursor || hasLimit,
    "GET /payment_intents needs pagination query params (limit/offset, page, or cursor)"
  );
}

function checkStep06(spec) {
  checkStep05(spec);
  const schemes = spec.components?.securitySchemes;
  assert(schemes && Object.keys(schemes).length > 0, "components.securitySchemes required");
  const rootSecurity = Array.isArray(spec.security) && spec.security.length > 0;
  const opSecurity = [
    "paths./payment_intents.get",
    "paths./payment_intents.post",
    "paths./payment_intents/{id}.get",
  ].some((p) => {
    const op = get(spec, p);
    return Array.isArray(op?.security) && op.security.length > 0;
  });
  assert(rootSecurity || opSecurity, "security must be applied at root or on an operation");
}

function checkStep07(spec) {
  assert(typeof spec.openapi === "string" && spec.openapi.startsWith("3."), "openapi version 3.x required");
  assert(typeof spec.info?.title === "string" && spec.info.title.length > 0, "info.title required");
  assert(typeof spec.info?.version === "string" && spec.info.version.length > 0, "info.version required");

  assert(get(spec, "paths./payment_intents.post"), "POST /payment_intents required");
  assert(get(spec, "paths./payment_intents.get"), "GET /payment_intents required");
  assert(get(spec, "paths./payment_intents/{paymentIntentId}.get"), "GET /payment_intents/{paymentIntentId} required");
  assert(
    get(spec, "paths./payment_intents/{paymentIntentId}/capture.post"),
    "POST /payment_intents/{paymentIntentId}/capture required"
  );
  assert(
    get(spec, "paths./payment_intents/{paymentIntentId}/refunds.post"),
    "POST /payment_intents/{paymentIntentId}/refunds required"
  );
  assert(get(spec, "paths./refunds/{refundId}.get"), "GET /refunds/{refundId} required");
  assert(get(spec, "paths./events/{eventId}.get"), "GET /events/{eventId} required");

  for (const name of ["PaymentIntent", "Capture", "Refund", "WebhookEvent", "Error"]) {
    assert(get(spec, `components.schemas.${name}`), `components.schemas.${name} required`);
  }

  const createIntent = get(spec, "paths./payment_intents.post");
  assert(createIntent.requestBody, "POST /payment_intents requestBody required");
  assert(
    createIntent.responses?.["201"] || createIntent.responses?.["200"],
    "POST /payment_intents success response required"
  );
  assert(createIntent.responses?.["400"], "POST /payment_intents 400 required");
  assert(
    get(spec, "paths./payment_intents/{paymentIntentId}.get").responses?.["404"],
    "GET payment intent 404 required"
  );
}

const CHECKERS = {
  "01": checkStep01,
  "02": checkStep02,
  "03": checkStep03,
  "04": checkStep04,
  "05": checkStep05,
  "06": checkStep06,
  "07": checkStep07,
};

function resolveStepId(raw) {
  const cleaned = String(raw).replace(/^0+/, "") || "0";
  const padded = cleaned.padStart(2, "0");
  if (!STEPS[padded] && !NO_CHECK_STEPS.has(padded)) {
    fail(`unknown step "${raw}". Use 00..07`);
  }
  return padded;
}

function checkOne(stepId, useSolutions) {
  const folder = STEPS[stepId];
  const filePath = useSolutions
    ? path.join(ROOT, "solutions", folder, "openapi.yaml")
    : path.join(ROOT, folder, "openapi.yaml");
  console.log(`check:step ${stepId} -> ${path.relative(ROOT, filePath)}`);
  const spec = loadSpec(filePath);
  lintFile(filePath);
  CHECKERS[stepId](spec);
  console.log(`ok: step ${stepId}`);
}

function main() {
  const args = process.argv.slice(2).filter((a) => a !== "--");
  const useSolutions = args.includes("--solutions");
  const allSolutions = args.includes("--all-solutions");
  const positional = args.filter((a) => !a.startsWith("--"));

  if (allSolutions) {
    for (const stepId of Object.keys(STEPS)) {
      checkOne(stepId, true);
    }
    console.log("ok: all solutions");
    return;
  }

  if (positional.length !== 1) {
    fail("usage: npm run check:step -- <01-07> [--solutions]");
  }

  checkOne(resolveStepId(positional[0]), useSolutions);
}

main();

/**
 * Baseline at scale: open a new Postgres connection per request, query the
 * unpartitioned events table, and hold the connection until the query ends.
 * Under k6 this exhausts max_connections and starts failing.
 */
import http from "node:http";
import pg from "pg";

const PORT = Number(process.env.PORT || 5401);
const DATABASE_URL =
  process.env.DATABASE_URL ||
  "postgres://exercise:exercise@127.0.0.1:5433/events";

async function handleEvents(userId) {
  const client = new pg.Client({ connectionString: DATABASE_URL });
  await client.connect();
  try {
    const { rows } = await client.query(
      `SELECT user_id, COUNT(*)::int AS n
       FROM events
       WHERE user_id = $1
         AND created_at >= '2024-06-01'
         AND created_at < '2024-10-01'
       GROUP BY user_id`,
      [userId]
    );
    return rows[0] || { user_id: userId, n: 0 };
  } finally {
    await client.end();
  }
}

const server = http.createServer(async (req, res) => {
  try {
    if (req.url === "/health") {
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify({ ok: true, mode: "baseline" }));
      return;
    }
    if (req.url?.startsWith("/events")) {
      const url = new URL(req.url, "http://local");
      const userId = Number(url.searchParams.get("user_id") || 42);
      const body = await handleEvents(userId);
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify(body));
      return;
    }
    res.writeHead(404);
    res.end("not found");
  } catch (err) {
    res.writeHead(503, { "content-type": "application/json" });
    res.end(
      JSON.stringify({
        error: "postgres_unavailable",
        message: String(err.message || err),
      })
    );
  }
});

server.listen(PORT, () => {
  console.log(
    `baseline listening on ${PORT} (direct Postgres, no pool, flat table)`
  );
});

/**
 * Better at scale:
 * - writes / admin through PgBouncer (transaction pooling)
 * - reads from the replica
 * - queries partitioned events_part (prunes old partitions)
 */
import http from "node:http";
import pg from "pg";

const PORT = Number(process.env.PORT || 5402);
const WRITE_URL =
  process.env.PGBOUNCER_URL ||
  "postgres://exercise:exercise@127.0.0.1:6432/events";
const READ_URL =
  process.env.REPLICA_URL ||
  "postgres://exercise:exercise@127.0.0.1:5434/events";

const writePool = new pg.Pool({
  connectionString: WRITE_URL,
  max: 20,
});
const readPool = new pg.Pool({
  connectionString: READ_URL,
  max: 20,
});

async function readEvents(userId) {
  const { rows } = await readPool.query(
    `SELECT user_id, COUNT(*)::int AS n
     FROM events_part
     WHERE user_id = $1
       AND created_at >= '2024-06-01'
       AND created_at < '2024-10-01'
     GROUP BY user_id`,
    [userId]
  );
  return rows[0] || { user_id: userId, n: 0 };
}

async function explainRead(userId) {
  const { rows } = await readPool.query(
    `EXPLAIN (FORMAT TEXT)
     SELECT user_id, COUNT(*)::int AS n
     FROM events_part
     WHERE user_id = $1
       AND created_at >= '2024-06-01'
       AND created_at < '2024-10-01'
     GROUP BY user_id`,
    [userId]
  );
  return rows.map((r) => r["QUERY PLAN"]);
}

const server = http.createServer(async (req, res) => {
  try {
    if (req.url === "/health") {
      await writePool.query("SELECT 1");
      await readPool.query("SELECT 1");
      res.writeHead(200, { "content-type": "application/json" });
      res.end(
        JSON.stringify({
          ok: true,
          mode: "better",
          write: "pgbouncer",
          read: "replica",
          table: "events_part",
        })
      );
      return;
    }
    if (req.url?.startsWith("/events")) {
      const url = new URL(req.url, "http://local");
      const userId = Number(url.searchParams.get("user_id") || 42);
      if (url.searchParams.get("explain") === "1") {
        const plan = await explainRead(userId);
        res.writeHead(200, { "content-type": "application/json" });
        res.end(JSON.stringify({ plan }));
        return;
      }
      const body = await readEvents(userId);
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify(body));
      return;
    }
    res.writeHead(404);
    res.end("not found");
  } catch (err) {
    res.writeHead(503, { "content-type": "application/json" });
    res.end(
      JSON.stringify({
        error: "postgres_unavailable",
        message: String(err.message || err),
      })
    );
  }
});

server.listen(PORT, () => {
  console.log(
    `better listening on ${PORT} (PgBouncer writes, replica reads, partitioned)`
  );
});

import http from "k6/http";
import { check, sleep } from "k6";
import { Rate, Trend } from "k6/metrics";

const TARGET = __ENV.TARGET || "http://127.0.0.1:5401";
const errorRate = new Rate("errors");
const latency = new Trend("events_latency", true);

export const options = {
  stages: [
    { duration: "10s", target: 20 },
    { duration: "20s", target: 80 },
    { duration: "20s", target: 150 },
    { duration: "10s", target: 0 },
  ],
  thresholds: {
    errors: ["rate<0.2"],
    events_latency: ["p(95)<500"],
  },
};

export default function () {
  const userId = Math.floor(Math.random() * 200) + 1;
  const res = http.get(`${TARGET}/events?user_id=${userId}`, {
    timeout: "3s",
  });
  const ok = check(res, { "status 200": (r) => r.status === 200 });
  errorRate.add(!ok);
  latency.add(res.timings.duration);
  sleep(0.05);
}

export function handleSummary(data) {
  const out = {
    target: TARGET,
    http_req_failed: data.metrics.http_req_failed?.values || {},
    errors: data.metrics.errors?.values || {},
    events_latency: data.metrics.events_latency?.values || {},
  };
  return {
    stdout: JSON.stringify(out, null, 2) + "\n",
    "k6-summary.json": JSON.stringify(out, null, 2),
  };
}

{
  "name": "postgres-scaling",
  "private": true,
  "type": "module",
  "scripts": {
    "seed": "node scripts/seed.js",
    "baseline": "node baseline/server.js",
    "better": "node better/api/server.js",
    "compare": "node scripts/compare.js",
    "partition-check": "node scripts/partition-check.js"
  },
  "dependencies": {
    "pg": "^8.13.1"
  }
}

import fs from "node:fs";

function load(path) {
  if (!fs.existsSync(path)) return null;
  return JSON.parse(fs.readFileSync(path, "utf8"));
}

const baseline = load("k6-summary-baseline.json") || load("k6-summary.json");
const better = load("k6-summary-better.json");

console.log("=== Postgres scale compare ===");
console.log(
  "Run k6 twice and save summaries:\n" +
    "  TARGET=http://127.0.0.1:5401 k6 run k6/load.js --summary-export=k6-summary-baseline.json\n" +
    "  TARGET=http://127.0.0.1:5402 k6 run k6/load.js --summary-export=k6-summary-better.json\n"
);
console.log("baseline=", baseline);
console.log("better=", better);
if (baseline && better) {
  const bFail = baseline.http_req_failed?.rate ?? baseline.errors?.rate;
  const aFail = better.http_req_failed?.rate ?? better.errors?.rate;
  const bP95 = baseline.events_latency?.["p(95)"];
  const aP95 = better.events_latency?.["p(95)"];
  console.log({ baseline_fail_rate: bFail, better_fail_rate: aFail, baseline_p95: bP95, better_p95: aP95 });
}

import pg from "pg";

const READ_URL =
  process.env.REPLICA_URL ||
  "postgres://exercise:exercise@127.0.0.1:5434/events";

const client = new pg.Client({ connectionString: READ_URL });
await client.connect();
const { rows } = await client.query(`
  EXPLAIN (FORMAT TEXT)
  SELECT user_id, COUNT(*)::int AS n
  FROM events_part
  WHERE user_id = 42
    AND created_at >= '2024-06-01'
    AND created_at < '2024-10-01'
  GROUP BY user_id
`);
console.log(rows.map((r) => r["QUERY PLAN"]).join("\n"));
const text = rows.map((r) => r["QUERY PLAN"]).join("\n");
console.log(
  text.includes("events_part_2024_h2") || text.includes("Partition")
    ? "partition_prune=likely"
    : "partition_prune=check_plan"
);
await client.end();

/**
 * Seed unpartitioned events on primary (baseline) and partitioned events
 * on primary + replica (better). Keeps data volume modest but enough to hurt
 * under connection storms.
 */
import pg from "pg";

const PRIMARY =
  process.env.PRIMARY_URL ||
  "postgres://exercise:exercise@127.0.0.1:5433/events";
const REPLICA =
  process.env.REPLICA_URL ||
  "postgres://exercise:exercise@127.0.0.1:5434/events";

const USERS = 200;
const EVENTS_PER_USER = 100;

async function seedFlat(client) {
  await client.query(`
    DROP TABLE IF EXISTS events CASCADE;
    CREATE TABLE events (
      id BIGSERIAL PRIMARY KEY,
      user_id INT NOT NULL,
      kind TEXT NOT NULL,
      created_at TIMESTAMPTZ NOT NULL
    );
  `);
  await insertEvents(client, "events");
  await client.query("ANALYZE events");
}

async function seedPartitioned(client) {
  await client.query(`
    DROP TABLE IF EXISTS events_part CASCADE;
    CREATE TABLE events_part (
      id BIGSERIAL,
      user_id INT NOT NULL,
      kind TEXT NOT NULL,
      created_at TIMESTAMPTZ NOT NULL,
      PRIMARY KEY (id, created_at)
    ) PARTITION BY RANGE (created_at);

    CREATE TABLE events_part_2024_h1 PARTITION OF events_part
      FOR VALUES FROM ('2024-01-01') TO ('2024-07-01');
    CREATE TABLE events_part_2024_h2 PARTITION OF events_part
      FOR VALUES FROM ('2024-07-01') TO ('2025-01-01');
    CREATE TABLE events_part_2025_h1 PARTITION OF events_part
      FOR VALUES FROM ('2025-01-01') TO ('2025-07-01');

    CREATE INDEX events_part_user_created_idx
      ON events_part (user_id, created_at);
  `);
  await insertEvents(client, "events_part");
  await client.query("ANALYZE events_part");
}

async function insertEvents(client, table) {
  const start = Date.UTC(2024, 0, 1);
  const dayMs = 86400000;
  const kinds = ["page_view", "click", "signup", "purchase"];
  for (let u = 1; u <= USERS; u += 1) {
    const values = [];
    const params = [];
    let p = 1;
    for (let i = 0; i < EVENTS_PER_USER; i += 1) {
      const created = new Date(start + ((u * 11 + i * 5) % 400) * dayMs);
      values.push(`($${p++}, $${p++}, $${p++})`);
      params.push(u, kinds[i % kinds.length], created.toISOString());
    }
    await client.query(
      `INSERT INTO ${table} (user_id, kind, created_at) VALUES ${values.join(",")}`,
      params
    );
  }
}

async function main() {
  const primary = new pg.Client({ connectionString: PRIMARY });
  await primary.connect();
  console.log("Seeding primary (flat + partitioned)...");
  await seedFlat(primary);
  await seedPartitioned(primary);
  const { rows } = await primary.query("SELECT COUNT(*)::int AS n FROM events");
  console.log(`primary events=${rows[0].n}`);
  await primary.end();

  const replica = new pg.Client({ connectionString: REPLICA });
  await replica.connect();
  console.log("Seeding replica (read copy of partitioned table)...");
  await seedPartitioned(replica);
  const r = await replica.query("SELECT COUNT(*)::int AS n FROM events_part");
  console.log(`replica events_part=${r.rows[0].n}`);
  await replica.end();
  console.log("Seed complete.");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

/**
 * Baseline at scale: every flag decision makes a network call to a stub
 * "Optimizely CDN / decide API". That latency multiplies under k6 and is
 * hostile to edge runtimes.
 */
import http from "node:http";

const PORT = Number(process.env.PORT || 3071);
const CDN_PORT = Number(process.env.CDN_PORT || 3070);
const CDN_DELAY_MS = Number(process.env.CDN_DELAY_MS || 40);

// Stub remote decide API (simulates Optimizely network hop).
http
  .createServer(async (req, res) => {
    await new Promise((r) => setTimeout(r, CDN_DELAY_MS));
    if (!req.url?.startsWith("/v1/decide")) {
      res.writeHead(404);
      res.end("not found");
      return;
    }
    const url = new URL(req.url, "http://cdn");
    const userId = url.searchParams.get("userId") || "anon";
    // Stable but remote: hash user id into two buckets.
    let h = 0;
    for (let i = 0; i < userId.length; i += 1) h = (h * 31 + userId.charCodeAt(i)) >>> 0;
    const variation = h % 100 < 50 ? "checklist_v1" : "checklist_v2";
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ variationKey: variation, source: "network" }));
  })
  .listen(CDN_PORT, () => {
    console.log(`stub Optimizely CDN on ${CDN_PORT} delay=${CDN_DELAY_MS}ms`);
  });

http
  .createServer(async (req, res) => {
    try {
      if (req.url === "/health") {
        res.writeHead(200, { "content-type": "application/json" });
