/**
 * Baseline at scale: every GET hits Postgres with artificial query delay.
 * No Redis. Hot key stampedes the database under k6.
 */
import http from "node:http";
import pg from "pg";

const PORT = Number(process.env.PORT || 5201);
const DATABASE_URL =
  process.env.DATABASE_URL ||
  "postgres://exercise:exercise@127.0.0.1:5435/catalog";
const QUERY_DELAY_MS = Number(process.env.QUERY_DELAY_MS || 50);

const pool = new pg.Pool({ connectionString: DATABASE_URL, max: 20 });
let dbQueries = 0;

async function loadProduct(id) {
  dbQueries += 1;
  await new Promise((r) => setTimeout(r, QUERY_DELAY_MS));
  const { rows } = await pool.query(
    "SELECT id, name, price_cents, inventory FROM products WHERE id = $1",
    [id]
  );
  return rows[0] || null;
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (c) => chunks.push(c));
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

const server = http.createServer(async (req, res) => {
  try {
    if (req.url === "/health") {
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify({ ok: true, mode: "baseline", dbQueries }));
      return;
    }
    if (req.url?.startsWith("/products/") && req.method === "GET") {
      const id = Number(req.url.slice("/products/".length));
      const t0 = performance.now();
      const product = await loadProduct(id);
      if (!product) {
        res.writeHead(404, { "content-type": "application/json" });
        res.end(JSON.stringify({ error: "not_found" }));
        return;
      }
      res.writeHead(200, { "content-type": "application/json" });
      res.end(
        JSON.stringify({
          ...product,
          cache: "miss",
          dbQueries,
          ms: +(performance.now() - t0).toFixed(2),
        })
      );
      return;
    }
    if (req.url?.startsWith("/products/") && req.method === "POST") {
      const id = Number(req.url.slice("/products/".length));
      const body = JSON.parse((await readBody(req)) || "{}");
      await pool.query(
        "UPDATE products SET inventory = $2 WHERE id = $1",
        [id, Number(body.inventory)]
      );
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify({ ok: true, id, inventory: Number(body.inventory) }));
      return;
    }
    res.writeHead(404);
    res.end("not found");
  } catch (err) {
    res.writeHead(500, { "content-type": "application/json" });
    res.end(JSON.stringify({ error: String(err.message || err) }));
  }
});

server.listen(PORT, () => {
  console.log(`baseline catalog on ${PORT} (Postgres only, delay=${QUERY_DELAY_MS}ms)`);
});

/**
 * Cache-aside helpers: get/set with TTL, delete on write, and singleflight
 * stampede protection (in-process coalescing + Redis SETNX lock).
 */
export function createCache(redis, opts = {}) {
  const ttlSeconds = opts.ttlSeconds || 30;
  const lockTtlMs = opts.lockTtlMs || 2000;
  const inflight = new Map();
  const stats = { hits: 0, misses: 0, fills: 0, coalesced: 0, lockWaits: 0 };

  function keyFor(id) {
    return `product:${id}`;
  }

  async function get(id) {
    const raw = await redis.get(keyFor(id));
    if (raw) {
      stats.hits += 1;
      return JSON.parse(raw);
    }
    stats.misses += 1;
    return null;
  }

  async function set(id, value) {
    await redis.set(keyFor(id), JSON.stringify(value), "EX", ttlSeconds);
  }

  async function invalidate(id) {
    await redis.del(keyFor(id));
  }

  /**
   * Load through cache with stampede protection:
   * 1) in-process singleflight for the same key
   * 2) Redis SETNX lock so multiple processes do one fill
   */
  async function getOrLoad(id, loader) {
    const cached = await get(id);
    if (cached) return { value: cached, cache: "hit" };

    if (inflight.has(id)) {
      stats.coalesced += 1;
      const value = await inflight.get(id);
      return { value, cache: "coalesced" };
    }

    const promise = (async () => {
      const lockKey = `lock:product:${id}`;
      const token = `${process.pid}-${Date.now()}-${Math.random()}`;
      const gotLock = await redis.set(lockKey, token, "PX", lockTtlMs, "NX");
      if (!gotLock) {
        stats.lockWaits += 1;
        for (let i = 0; i < 20; i += 1) {
          await new Promise((r) => setTimeout(r, 25));
          const again = await redis.get(keyFor(id));
          if (again) return JSON.parse(again);
        }
      }
      try {
        const still = await redis.get(keyFor(id));
        if (still) return JSON.parse(still);
        stats.fills += 1;
        const value = await loader(id);
        if (value) await set(id, value);
        return value;
      } finally {
        const current = await redis.get(lockKey);
        if (current === token) await redis.del(lockKey);
      }
    })();

    inflight.set(id, promise);
    try {
      const value = await promise;
      return { value, cache: "miss_fill" };
    } finally {
      inflight.delete(id);
    }
  }

  return { get, set, invalidate, getOrLoad, stats: () => ({ ...stats }), ttlSeconds };
}

/**
 * Better at scale: Redis cache-aside, TTL, invalidate-on-write,
 * stampede protection on hot keys.
 */
import http from "node:http";
import pg from "pg";
import Redis from "ioredis";
import { createCache } from "./cache.js";

const PORT = Number(process.env.PORT || 5202);
const DATABASE_URL =
  process.env.DATABASE_URL ||
  "postgres://exercise:exercise@127.0.0.1:5435/catalog";
const REDIS_URL = process.env.REDIS_URL || "redis://127.0.0.1:6379";
const QUERY_DELAY_MS = Number(process.env.QUERY_DELAY_MS || 50);

const pool = new pg.Pool({ connectionString: DATABASE_URL, max: 20 });
const redis = new Redis(REDIS_URL, { maxRetriesPerRequest: 1 });
const cache = createCache(redis, { ttlSeconds: 30, lockTtlMs: 2000 });
let dbQueries = 0;

async function loadProduct(id) {
  dbQueries += 1;
  await new Promise((r) => setTimeout(r, QUERY_DELAY_MS));
  const { rows } = await pool.query(
    "SELECT id, name, price_cents, inventory FROM products WHERE id = $1",
    [id]
  );
  return rows[0] || null;
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (c) => chunks.push(c));
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

const server = http.createServer(async (req, res) => {
  try {
    if (req.url === "/health") {
      res.writeHead(200, { "content-type": "application/json" });
      res.end(
        JSON.stringify({
          ok: true,
          mode: "better",
          dbQueries,
          cache: cache.stats(),
        })
      );
      return;
    }
    if (req.url?.startsWith("/products/") && req.method === "GET") {
      const id = Number(req.url.slice("/products/".length));
      const t0 = performance.now();
      const { value, cache: cacheMode } = await cache.getOrLoad(id, loadProduct);
      if (!value) {
        res.writeHead(404, { "content-type": "application/json" });
        res.end(JSON.stringify({ error: "not_found" }));
        return;
      }
      res.writeHead(200, { "content-type": "application/json" });
      res.end(
        JSON.stringify({
          ...value,
          cache: cacheMode,
          dbQueries,
          cacheStats: cache.stats(),
          ms: +(performance.now() - t0).toFixed(2),
        })
      );
      return;
    }
    if (req.url?.startsWith("/products/") && req.method === "POST") {
      const id = Number(req.url.slice("/products/".length));
      const body = JSON.parse((await readBody(req)) || "{}");
      await pool.query(
        "UPDATE products SET inventory = $2 WHERE id = $1",
        [id, Number(body.inventory)]
      );
      await cache.invalidate(id);
      res.writeHead(200, { "content-type": "application/json" });
      res.end(
        JSON.stringify({
          ok: true,
          id,
          inventory: Number(body.inventory),
          invalidated: true,
        })
      );
      return;
    }
    res.writeHead(404);
    res.end("not found");
  } catch (err) {
    res.writeHead(500, { "content-type": "application/json" });
    res.end(JSON.stringify({ error: String(err.message || err) }));
  }
});

server.listen(PORT, () => {
  console.log(
    `better catalog on ${PORT} (Redis cache-aside + TTL + invalidate + stampede lock)`
  );
});

import http from "k6/http";
import { check, sleep } from "k6";
import { Trend } from "k6/metrics";

const TARGET = __ENV.TARGET || "http://127.0.0.1:5201";
const HOT_ID = __ENV.HOT_ID || "1";
const latency = new Trend("product_ms", true);

export const options = {
  stages: [
    { duration: "8s", target: 20 },
    { duration: "20s", target: 80 },
    { duration: "8s", target: 0 },
  ],
  thresholds: {
    http_req_failed: ["rate<0.05"],
  },
};

export default function () {
  // 70% traffic on the hot key to provoke stampedes in baseline.
  const id = Math.random() < 0.7 ? HOT_ID : String(Math.floor(Math.random() * 200) + 1);
  const res = http.get(`${TARGET}/products/${id}`);
  check(res, { "200": (r) => r.status === 200 });
  try {
    const body = res.json();
    if (body && typeof body.ms === "number") latency.add(body.ms);
    else latency.add(res.timings.duration);
  } catch {
    latency.add(res.timings.duration);
  }
  sleep(0.02);
}

export function handleSummary(data) {
  const out = {
    target: TARGET,
    http_req_duration: data.metrics.http_req_duration?.values || {},
    product_ms: data.metrics.product_ms?.values || {},
  };
  return {
    stdout: JSON.stringify(out, null, 2) + "\n",
    "k6-summary.json": JSON.stringify(out, null, 2),
  };
}

